// Collect all processed sources
const allSources = $input.all();
const result = {};

// Build the final structure with separate sources
allSources.forEach(item => {
  const sourceData = item.json;
  const sourceName = sourceData.source;

  // Use the source name as key and the data array as value
  result[sourceName] = sourceData.data || [];
});

