// CVE Deduplicator for n8n workflow
// This code should be placed in a Code node after "Create Final Structure"

const inputData = $input.first().json;

// Helper functions for extracting CVE IDs
function extractCveIdFromNvd(vuln) {
  return vuln?.cve?.id;
}

function extractCveIdFromVuldb(entry) {
  return entry?.source?.cve?.id;
}

function extractCveIdFromCvefind(entry) {
  return entry?.id;
}

function extractCveIdFromOpencve(entry) {
  return entry?.cve_id;
}

// Normalization functions
function normalizeNvdCve(vuln) {
  const cveData = vuln?.cve || {};

  // Extract CVSS data
  let cvssData = {};
  const metrics = cveData?.metrics || {};
  if (metrics.cvssMetricV31 && metrics.cvssMetricV31.length > 0) {
    const primaryCvss = metrics.cvssMetricV31.find(m => m.type === "Primary") || metrics.cvssMetricV31[0];
    const cvssInfo = primaryCvss?.cvssData || {};
    cvssData = {
      version: cvssInfo.version,
      vector: cvssInfo.vectorString,
      score: cvssInfo.baseScore,
      severity: cvssInfo.baseSeverity
    };
  }

  // Extract description
  const descriptions = cveData?.descriptions || [];
  let description = "";
  if (descriptions.length > 0) {
    const enDesc = descriptions.find(d => d.lang === "en") || descriptions[0];
    description = enDesc?.value || "";
  }

  // Extract CWE information
  const cweList = [];
  const weaknesses = cveData?.weaknesses || [];
  weaknesses.forEach(weakness => {
    weakness?.description?.forEach(desc => {
      if (desc.lang === "en" && desc.value) {
        cweList.push(desc.value);
      }
    });
  });

  // Extract affected products/configurations
  const affectedProducts = [];
  const configurations = cveData?.configurations || [];
  configurations.forEach(config => {
    config?.nodes?.forEach(node => {
      node?.cpeMatch?.forEach(cpeMatch => {
        const cpeName = cpeMatch?.criteria || "";
        if (cpeName.startsWith("cpe:2.3:")) {
          const parts = cpeName.split(":");
          if (parts.length >= 6) {
            const vendor = parts[3] !== "*" ? parts[3] : "unknown";
            const product = parts[4] !== "*" ? parts[4] : "unknown";
            const version = parts[5] !== "*" ? parts[5] : "unknown";

            const productEntry = { vendor, product, version };
            if (!affectedProducts.some(p => JSON.stringify(p) === JSON.stringify(productEntry))) {
              affectedProducts.push(productEntry);
            }
          }
        }
      });
    });
  });

  // Extract references
  const references = [];
  (cveData?.references || []).forEach(ref => {
    if (ref?.url) {
      references.push(ref.url);
    }
  });

  // Check for exploit availability
  let exploitAvailable = false;
  (cveData?.references || []).forEach(ref => {
    const tags = ref?.tags || [];
    if (tags.some(tag => ["exploit", "exploit-db", "poc"].includes(tag.toLowerCase()))) {
      exploitAvailable = true;
    }
  });

  // Generate tags
  const tags = [];
  const descLower = description.toLowerCase();
  if (descLower.includes("idor") || descLower.includes("insecure direct object reference")) {
    tags.push("idor");
  }
  if (descLower.includes("access control") || descLower.includes("authorization")) {
    tags.push("access-control");
  }
  if (descLower.includes("sql injection")) {
    tags.push("sql-injection");
  }
  if (descLower.includes("xss") || descLower.includes("cross-site scripting")) {
    tags.push("xss");
  }
  if (descLower.includes("csrf") || descLower.includes("cross-site request forgery")) {
    tags.push("csrf");
  }

  // Add product names as tags
  affectedProducts.forEach(product => {
    const productName = product.product?.toLowerCase();
    if (productName && productName !== "unknown") {
      tags.push(productName);
    }
  });

  return {
    cve_id: cveData.id,
    published_date: cveData.published,
    last_modified: cveData.lastModified,
    source: "NVD",
    description,
    cvss: cvssData,
    cwe: cweList,
    affected_products: affectedProducts,
    references,
    exploit_available: exploitAvailable,
    tags
  };
}

function normalizeVuldbCve(entry) {
  const entryData = entry?.entry || {};
  const vulnerability = entry?.vulnerability || {};
  const risk = vulnerability?.risk || {};
  const advisory = entry?.advisory || {};

  // Convert timestamps
  let publishedDate = null;
  let lastModified = null;

  if (advisory.date) {
    try {
      publishedDate = new Date(parseInt(advisory.date) * 1000).toISOString();
    } catch (e) {
      publishedDate = null;
    }
  }

  const timestamp = entryData?.timestamp || {};
  if (timestamp.change) {
    try {
      lastModified = new Date(parseInt(timestamp.change) * 1000).toISOString();
    } catch (e) {
      lastModified = null;
    }
  }

  // Parse title for product info
  const title = entryData?.title || "";
  const affectedProducts = [];

  if (title) {
    const parts = title.split(" ");
    const versionIndicators = ["prior", "up", "to", "version", "v", "before"];

    let vendor = "";
    let product = "";
    let version = "";

    for (let i = 0; i < parts.length; i++) {
      if (versionIndicators.includes(parts[i].toLowerCase()) && i + 1 < parts.length) {
        const vendorProduct = parts.slice(0, i).join(" ");
        version = parts[i + 1];

        const vpParts = vendorProduct.split(" ");
        if (vpParts.length >= 2) {
          vendor = vpParts[0];
          product = vpParts.slice(1).join(" ");
        } else {
          vendor = "unknown";
          product = vendorProduct;
        }
        break;
      }
    }

    if (!vendor && !product && parts.length >= 2) {
      vendor = parts[0];
      product = parts[1];
      version = "unknown";
    }

    if (vendor || product) {
      affectedProducts.push({
        vendor: vendor || "unknown",
        product: product || "unknown",
        version: version || "unknown"
      });
    }
  }

  // Generate tags
  const tags = [];
  const titleLower = title.toLowerCase();

  if (titleLower.includes("cross site scripting") || titleLower.includes("xss")) {
    tags.push("xss");
  }
  if (titleLower.includes("sql injection")) {
    tags.push("sql-injection");
  }
  if (titleLower.includes("command injection")) {
    tags.push("command-injection");
  }
  if (titleLower.includes("unrestricted upload") || titleLower.includes("file upload")) {
    tags.push("unrestricted-upload");
  }
  if (titleLower.includes("csrf")) {
    tags.push("csrf");
  }

  return {
    cve_id: extractCveIdFromVuldb(entry),
    published_date: publishedDate,
    last_modified: lastModified,
    source: "VulDB",
    description: title,
    cvss: {
      version: null,
      vector: null,
      score: null,
      severity: risk?.name?.toLowerCase() || "unknown"
    },
    cwe: [],
    affected_products: affectedProducts,
    references: [],
    exploit_available: false,
    tags
  };
}

function normalizeCvefindCve(entry) {
  const references = [];
  (entry?.references || []).forEach(ref => {
    if (typeof ref === "object" && ref?.url) {
      references.push(ref.url);
    } else if (typeof ref === "string") {
      references.push(ref);
    }
  });

  return {
    cve_id: entry?.id,
    published_date: entry?.published,
    last_modified: entry?.lastModified,
    source: "CVEFind",
    description: entry?.description || "",
    cvss: {
      version: entry?.cvssVersion,
      score: entry?.baseScore ? parseFloat(entry.baseScore) : null,
      attack_vector: entry?.attackVector,
      attack_complexity: entry?.attackComplexity
    },
    cwe: [],
    affected_products: [],
    references,
    exploit_available: false,
    tags: []
  };
}

function normalizeOpencveCve(entry) {
  const references = [];
  if (entry?.cve_url) {
    references.push(entry.cve_url);
  }

  // Extract affected products from products and vendors arrays
  const affectedProducts = [];
  const products = entry?.products || [];
  const vendors = entry?.vendors || [];

  // Create product entries by combining vendors and products
  if (vendors.length > 0 && products.length > 0) {
    vendors.forEach(vendor => {
      products.forEach(product => {
        affectedProducts.push({
          vendor: vendor,
          product: product,
          version: "unknown"
        });
      });
    });
  } else if (products.length > 0) {
    // If only products, use "unknown" vendor
    products.forEach(product => {
      affectedProducts.push({
        vendor: "unknown",
        product: product,
        version: "unknown"
      });
    });
  } else if (vendors.length > 0) {
    // If only vendors, use vendor as product
    vendors.forEach(vendor => {
      affectedProducts.push({
        vendor: vendor,
        product: "unknown",
        version: "unknown"
      });
    });
  }

  // Generate tags from summary and products
  const tags = [];
  const summary = (entry?.summary || "").toLowerCase();

  if (summary.includes("cross-site request forgery") || summary.includes("csrf")) {
    tags.push("csrf");
  }
  if (summary.includes("cross-site scripting") || summary.includes("xss")) {
    tags.push("xss");
  }
  if (summary.includes("sql injection")) {
    tags.push("sql-injection");
  }
  if (summary.includes("denial of service") || summary.includes("dos")) {
    tags.push("dos");
  }
  if (summary.includes("access control") || summary.includes("authorization")) {
    tags.push("access-control");
  }
  if (summary.includes("idor") || summary.includes("insecure direct object reference")) {
    tags.push("idor");
  }
  if (summary.includes("remote code execution") || summary.includes("rce")) {
    tags.push("rce");
  }

  // Add product names as tags
  products.forEach(product => {
    if (product && product.toLowerCase() !== "unknown") {
      tags.push(product.toLowerCase());
    }
  });

  return {
    cve_id: entry?.cve_id,
    published_date: entry?.updated_date ? entry.updated_date + "T00:00:00Z" : null,
    last_modified: entry?.updated_date ? entry.updated_date + "T00:00:00Z" : null,
    source: "OpenCVE",
    description: entry?.summary || "",
    cvss: {
      version: null,
      vector: null,
      score: entry?.cvss_score,
      severity: entry?.cvss_severity
    },
    cwe: [],
    affected_products: affectedProducts,
    references,
    exploit_available: false,
    tags,
    products: entry?.products || [],
    vendors: entry?.vendors || []
  };
}

// Main processing function
function processCveData(data) {
  const allCves = {};

  // Process NVD data
  if (data.NVD && data.NVD.vulnerabilities) {
    data.NVD.vulnerabilities.forEach(vuln => {
      const cveId = extractCveIdFromNvd(vuln);
      if (cveId) {
        const normalized = normalizeNvdCve(vuln);
        if (!allCves[cveId]) {
          allCves[cveId] = normalized;
        } else {
          allCves[cveId].sources = allCves[cveId].sources || [allCves[cveId].source];
          allCves[cveId].sources.push("NVD");
        }
      }
    });
  }

  // Process VulDB data
  if (data.VulDB && data.VulDB.result) {
    data.VulDB.result.forEach(entry => {
      const cveId = extractCveIdFromVuldb(entry);
      if (cveId) {
        const normalized = normalizeVuldbCve(entry);
        if (!allCves[cveId]) {
          allCves[cveId] = normalized;
        } else {
          allCves[cveId].sources = allCves[cveId].sources || [allCves[cveId].source];
          allCves[cveId].sources.push("VulDB");
        }
      }
    });
  }

  // Process CVEFind data
  if (data.CVEFind && data.CVEFind.data) {
    data.CVEFind.data.forEach(entry => {
      const cveId = extractCveIdFromCvefind(entry);
      if (cveId) {
        const normalized = normalizeCvefindCve(entry);
        if (!allCves[cveId]) {
          allCves[cveId] = normalized;
        } else {
          allCves[cveId].sources = allCves[cveId].sources || [allCves[cveId].source];
          allCves[cveId].sources.push("CVEFind");
        }
      }
    });
  }

  // Process OpenCVE data
  if (data.OpenCVE && data.OpenCVE.cves) {
    data.OpenCVE.cves.forEach(entry => {
      const cveId = extractCveIdFromOpencve(entry);
      if (cveId) {
        const normalized = normalizeOpencveCve(entry);
        if (!allCves[cveId]) {
          allCves[cveId] = normalized;
        } else {
          allCves[cveId].sources = allCves[cveId].sources || [allCves[cveId].source];
          allCves[cveId].sources.push("OpenCVE");
        }
      }
    });
  }

  return allCves;
}

// Process the data
const deduplicatedCves = processCveData(inputData);

// Count sources
const sourceCounts = {};
Object.values(deduplicatedCves).forEach(cve => {
  const sources = cve.sources || [cve.source];
  sources.forEach(source => {
    sourceCounts[source] = (sourceCounts[source] || 0) + 1;
  });
});

// Create output structure
const output = {
  metadata: {
    generated_at: new Date().toISOString(),
    total_unique_cves: Object.keys(deduplicatedCves).length,
    original_sources: ["NVD", "VulDB", "CVEFind", "OpenCVE"],
    deduplication_method: "CVE ID based",
    source_counts: sourceCounts
  },
  cves: Object.values(deduplicatedCves)
};

console.log(`✅ Successfully processed ${Object.keys(deduplicatedCves).length} unique CVEs`);
console.log("📊 Source distribution:", sourceCounts);

// Prepare for file download with binary data
const jsonContent = JSON.stringify(output, null, 2);
const timestamp = new Date().toISOString().replace(/[:]/g, '-').replace(/[.]\d+Z/, '');
const fileName = `deduplicated-cves-${timestamp}.json`;

const fileSizeBytes = Buffer.byteLength(jsonContent, 'utf8');
const fileSizeKB = (fileSizeBytes / 1024).toFixed(2);

return [{
  json: {
    // This is the data you'll pass to the LLM
    cves: Object.values(deduplicatedCves),  // The actual deduplicated CVEs
    metadata: {
      total_unique_cves: Object.keys(deduplicatedCves).length,
      source_distribution: sourceCounts,
      generated_at: new Date().toISOString()
    },

    // Keep the download info if you still need it
    downloadInfo: {
      file_size_bytes: fileSizeBytes,
      file_size_kb: fileSizeKB + ' KB',
      generated_at: new Date().toISOString()
    }
  }
}];

