// Helper function to get CVSS multiplier based on score range
function getCvssMultiplier(cvssScore) {
  if (!cvssScore || cvssScore === null) return 0.8;

  const scoreRanges = Object.keys(SCORING_CONFIG.CVSS_SCORING)
    .map(Number)
    .sort((a, b) => b - a);

  for (const threshold of scoreRanges) {
    if (cvssScore >= threshold) {
      return SCORING_CONFIG.CVSS_SCORING[threshold].multiplier;
    }
  }

  return 0.5; // Very low score
}

// Helper function to calculate age multiplier
function getAgeMultiplier(publishedDate) {
  if (!publishedDate) return 1.0;

  const now = new Date();
  const published = new Date(publishedDate);
  const daysDiff = Math.floor((now - published) / (1000 * 60 * 60 * 24));

  const ageThresholds = Object.keys(SCORING_CONFIG.AGE_FACTORS)
    .map(Number)
    .sort((a, b) => a - b);

  for (const threshold of ageThresholds) {
    if (daysDiff <= threshold) {
      return SCORING_CONFIG.AGE_FACTORS[threshold].multiplier;
    }
  }

  return 0.8; // Very old
}

// Enhanced technology scoring with better matching
function calculateTechnologyScore(cve) {
  let maxScore = 0;
  let totalWeightedScore = 0;
  let totalWeight = 0;
  let matchedProducts = [];
  let categories = new Set();

  const searchText = [
    cve.description || '',
    ...(cve.affected_products?.map(p => `${p.vendor} ${p.product}`) || []),
    ...(cve.tags || [])
  ].join(' ').toLowerCase();

  // More intelligent matching
  Object.entries(SCORING_CONFIG.TECHNOLOGY_PRODUCTS).forEach(([tech, config]) => {
    const techWords = tech.split(' ');
    let matchScore = 0;
    let matchLocation = [];

    // Exact phrase match gets full score
    if (searchText.includes(tech)) {
      matchScore = config.score;
      matchLocation.push('exact_match');
    } 
    // Partial word matching for compound terms
    else if (techWords.length > 1 && techWords.every(word => searchText.includes(word))) {
      matchScore = config.score * 0.8; // 80% for partial match
      matchLocation.push('partial_match');
    }
    // Single word match with context
    else if (techWords.length === 1 && searchText.includes(tech)) {
      // Check for context to avoid false positives
      const regex = new RegExp(`\\b${tech}\\b`, 'i');
      if (regex.test(searchText)) {
        matchScore = config.score * 0.9; // 90% for single word with context
        matchLocation.push('word_boundary_match');
      }
    }

    if (matchScore > 0) {
      maxScore = Math.max(maxScore, matchScore);
      totalWeightedScore += matchScore * config.weight;
      totalWeight += config.weight;

      matchedProducts.push({
        technology: tech,
        score: matchScore,
        weight: config.weight,
        category: config.category,
        match_type: matchLocation.join(', ')
      });
      categories.add(config.category);
    }
  });

  // Calculate weighted average for more balanced scoring
  const weightedScore = totalWeight > 0 ? totalWeightedScore / totalWeight : 0;
  const finalScore = Math.min(100, Math.max(maxScore * 0.6 + weightedScore * 0.4, maxScore));

  return {
    score: Math.round(finalScore),
    max_score: Math.round(maxScore),
    weighted_score: Math.round(weightedScore),
    matched_products: matchedProducts,
    categories: Array.from(categories)
  };
}

// Enhanced vulnerability type scoring
function calculateVulnerabilityScore(cve) {
  let maxScore = 0;
  let totalWeightedScore = 0;
  let totalWeight = 0;
  let matchedTypes = [];

  const searchText = [
    cve.description || '',
    ...(cve.tags || []),
    ...(cve.cwe?.map(c => c.toLowerCase()) || [])
  ].join(' ').toLowerCase();

  Object.entries(SCORING_CONFIG.VULNERABILITY_TYPES).forEach(([vulnType, config]) => {
    if (searchText.includes(vulnType)) {
      maxScore = Math.max(maxScore, config.score);
      totalWeightedScore += config.score * config.weight;
      totalWeight += config.weight;

      matchedTypes.push({
        type: vulnType,
        score: config.score,
        weight: config.weight,
        impact: config.impact
      });
    }
  });

  const weightedScore = totalWeight > 0 ? totalWeightedScore / totalWeight : 0;
  const finalScore = Math.min(100, Math.max(maxScore * 0.7 + weightedScore * 0.3, maxScore));

  return {
    score: Math.round(finalScore),
    max_score: Math.round(maxScore),
    weighted_score: Math.round(weightedScore),
    matched_types: matchedTypes
  };
}

// Enhanced sector analysis
function calculateSectorMultiplier(categories) {
  let maxMultiplier = 1.0;
  let appliedSector = 'enterprise';

  // Banking/Financial gets highest priority
  if (categories.includes('banking_infrastructure') || categories.includes('banking_software')) {
    maxMultiplier = SCORING_CONFIG.SECTOR_MULTIPLIERS.banking;
    appliedSector = 'banking';
  }
  // Identity management is critical for all sectors
  else if (categories.includes('identity_management')) {
    maxMultiplier = SCORING_CONFIG.SECTOR_MULTIPLIERS.government;
    appliedSector = 'government';
  }
  // Network security infrastructure
  else if (categories.includes('network_security')) {
    maxMultiplier = SCORING_CONFIG.SECTOR_MULTIPLIERS.critical_infrastructure;
    appliedSector = 'critical_infrastructure';
  }
  // Hypervisors and virtualization
  else if (categories.includes('hypervisor') || categories.includes('virtualization')) {
    maxMultiplier = SCORING_CONFIG.SECTOR_MULTIPLIERS.critical_infrastructure;
    appliedSector = 'critical_infrastructure';
  }

  return {
    multiplier: maxMultiplier,
    sector: appliedSector
  };
}

// Main priority calculation with improved algorithm
function calculatePriorityScore(cve) {
  // Base component scores (0-100)
  const techAnalysis = calculateTechnologyScore(cve);
  const vulnAnalysis = calculateVulnerabilityScore(cve);

  // Calculate base score with proper weighting
  // Technology relevance: 40%, Vulnerability severity: 60%
  let baseScore = 0;

  if (techAnalysis.score > 0 && vulnAnalysis.score > 0) {
    // Both technology and vulnerability identified
    baseScore = (techAnalysis.score * 0.4) + (vulnAnalysis.score * 0.6);
  } else if (techAnalysis.score > 0) {
    // Only technology identified
    baseScore = techAnalysis.score * 0.7; // Reduced impact
  } else if (vulnAnalysis.score > 0) {
    // Only vulnerability type identified
    baseScore = vulnAnalysis.score * 0.5; // Significantly reduced
  } else {
    // Neither identified - use CVSS as fallback
    const cvssScore = cve.cvss?.score || 0;
    baseScore = Math.min(40, cvssScore * 4); // Cap at 40 for unknown tech/vuln
  }

  // Apply multipliers
  const cvssMultiplier = getCvssMultiplier(cve.cvss?.score);
  const ageMultiplier = getAgeMultiplier(cve.published_date);
  const sectorAnalysis = calculateSectorMultiplier(techAnalysis.categories);

  // Exploit availability multiplier
  let exploitMultiplier = SCORING_CONFIG.EXPLOIT_FACTORS.no_exploit.multiplier;
  if (cve.exploit_available) {
    exploitMultiplier = SCORING_CONFIG.EXPLOIT_FACTORS.public_exploit.multiplier;
  }

  // Geographic multiplier (default to global)
  let geoMultiplier = 1.0;
  const description = (cve.description || '').toLowerCase();
  Object.entries(SCORING_CONFIG.GEOGRAPHIC_FACTORS).forEach(([region, multiplier]) => {
    if (description.includes(region)) {
      geoMultiplier = Math.max(geoMultiplier, multiplier);
    }
  });

  // Final score calculation
  const finalScore = Math.min(100, Math.round(
    baseScore * 
    cvssMultiplier * 
    ageMultiplier * 
    sectorAnalysis.multiplier * 
    exploitMultiplier * 
    geoMultiplier
  ));

  // Determine priority level with better thresholds
  let priorityLevel;
  if (finalScore >= 85) priorityLevel = 'CRITICAL';
  else if (finalScore >= 65) priorityLevel = 'HIGH';
  else if (finalScore >= 40) priorityLevel = 'MEDIUM';
  else priorityLevel = 'LOW';

  return {
    priority_score: finalScore,
    priority_level: priorityLevel,
    scoring_breakdown: {
      base_score: Math.round(baseScore),
      technology_analysis: techAnalysis,
      vulnerability_analysis: vulnAnalysis,
      multipliers: {
        cvss: cvssMultiplier,
        age: ageMultiplier,
        sector: sectorAnalysis.multiplier,
        exploit: exploitMultiplier,
        geographic: geoMultiplier
      },
      sector_analysis: sectorAnalysis
    },
    risk_factors: {
      exploit_available: cve.exploit_available || false,
      cvss_score: cve.cvss?.score || null,
      cvss_severity: cve.cvss?.severity || 'unknown',
      age_days: cve.published_date ? Math.floor((new Date() - new Date(cve.published_date)) / (1000 * 60 * 60 * 24)) : null,
      affected_technologies: techAnalysis.categories,
      vulnerability_types: vulnAnalysis.matched_types.map(t => t.type),
      sector: sectorAnalysis.sector
    }
  };
}

// Main processing function
function processCveData(data) {
  if (!data.cves || !Array.isArray(data.cves)) {
    throw new Error('Invalid input: expected CVE data with cves array');
  }

  console.log(`🔄 Processing ${data.cves.length} CVEs with improved scoring algorithm...`);

  // Score all CVEs
  const scoredCves = data.cves.map(cve => ({
    ...cve,
    priority_scoring: calculatePriorityScore(cve)
  }));

  // Sort by priority score (highest first), then by CVSS score
  scoredCves.sort((a, b) => {
    if (b.priority_scoring.priority_score !== a.priority_scoring.priority_score) {
      return b.priority_scoring.priority_score - a.priority_scoring.priority_score;
    }
    return (b.cvss?.score || 0) - (a.cvss?.score || 0);
  });

  // Calculate statistics
  const stats = {
    total_cves: scoredCves.length,
    priority_distribution: {
      CRITICAL: scoredCves.filter(c => c.priority_scoring.priority_level === 'CRITICAL').length,
      HIGH: scoredCves.filter(c => c.priority_scoring.priority_level === 'HIGH').length,
      MEDIUM: scoredCves.filter(c => c.priority_scoring.priority_level === 'MEDIUM').length,
      LOW: scoredCves.filter(c => c.priority_scoring.priority_level === 'LOW').length
    },
    average_score: Math.round(
      scoredCves.reduce((sum, cve) => sum + cve.priority_scoring.priority_score, 0) / scoredCves.length
    ),
    score_ranges: {
      max: Math.max(...scoredCves.map(c => c.priority_scoring.priority_score)),
      min: Math.min(...scoredCves.map(c => c.priority_scoring.priority_score))
    }
  };

  return {
    fileName: `scored-cves-${new Date().toISOString().replace(/[:]/g, '-').replace(/[.]\d+Z/, '')}.json`,
    file_size_bytes: 0, // Will be calculated
    file_size_kb: "0 KB", // Will be calculated
    generated_at: new Date().toISOString(),
    total_scored_cves: stats.total_cves,
    priority_distribution: stats.priority_distribution,
    average_score: stats.average_score,
    scoring_algorithm_version: "2.0",
    improvements: [
      "Better weighted scoring algorithm",
      "Improved technology matching with context",
      "Age-based priority adjustment",
      "Enhanced vulnerability type detection",
      "Balanced multiplier application",
      "More accurate sector-based weighting"
    ],
    cves: scoredCves
  };
}

