// Function to filter CVEs with priority score >= 50
function filterCvesByPriorityScore(data, minimumScore = 50) {
  if (!data || typeof data !== 'object') {
    throw new Error('Invalid input: expected object with CVE data');
  }

  // Handle both array format and direct object format
  let cveData;
  if (Array.isArray(data)) {
    // If input is an array, take the first element
    cveData = data[0];
  } else {
    // If input is already an object
    cveData = data;
  }

  if (!cveData.cves || !Array.isArray(cveData.cves)) {
    throw new Error('Invalid input: expected CVE data with cves array');
  }

  // Filter CVEs with priority score >= minimumScore
  const filteredCves = cveData.cves.filter(cve => {
    const priorityScore = cve.priority_scoring?.priority_score || 0;
    return priorityScore >= minimumScore;
  });

  // Recalculate priority distribution for filtered data
  const priorityDistribution = {
    CRITICAL: filteredCves.filter(c => c.priority_scoring?.priority_level === 'CRITICAL').length,
    HIGH: filteredCves.filter(c => c.priority_scoring?.priority_level === 'HIGH').length,
    MEDIUM: filteredCves.filter(c => c.priority_scoring?.priority_level === 'MEDIUM').length,
    LOW: filteredCves.filter(c => c.priority_scoring?.priority_level === 'LOW').length
  };

  // Recalculate average score for filtered data
  const validScores = filteredCves
    .map(cve => cve.priority_scoring?.priority_score || 0)
    .filter(score => !isNaN(score) && score >= 0);

  const averageScore = validScores.length > 0 
    ? Math.round(validScores.reduce((sum, score) => sum + score, 0) / validScores.length)
    : 0;

  // Create filtered result with same structure
  const filteredResult = {
    fileName: cveData.fileName || `filtered-cves-${new Date().toISOString().replace(/[:]/g, '-').replace(/[.]\d+Z/, '')}.json`,
    file_size_bytes: cveData.file_size_bytes, // Will be recalculated below
    file_size_kb: cveData.file_size_kb, // Will be recalculated below
    generated_at: new Date().toISOString(),
    total_scored_cves: filteredCves.length,
    priority_distribution: priorityDistribution,
    average_score: averageScore,
    cves: filteredCves
  };

  // Recalculate file size for filtered data
  const jsonContent = JSON.stringify(filteredResult, null, 2);
  const fileSizeBytes = Buffer.byteLength(jsonContent, 'utf8');
  const fileSizeKB = (fileSizeBytes / 1024).toFixed(2);

  // Update file size information
  filteredResult.file_size_bytes = fileSizeBytes;
  filteredResult.file_size_kb = `${fileSizeKB} KB`;

  return filteredResult;
}

