// Function to generate risk level color
function getRiskColor(riskLevel) {
  if (!riskLevel) return '#6c757d';
  const levelLower = riskLevel.toLowerCase();
  const colors = {
    'critical': '#dc3545',
    'critique': '#dc3545',
    'high': '#fd7e14',
    'élevé': '#fd7e14',
    'important': '#fd7e14',
    'medium': '#ffc107',
    'moyen': '#ffc107',
    'low': '#28a745',
    'faible': '#28a745'
  };
  return colors[levelLower] || '#6c757d';
}

// Function to get risk level priority for sorting
function getRiskPriority(riskLevel) {
  if (!riskLevel) return 0;
  const levelLower = riskLevel.toLowerCase();
  const priorities = {
    'critical': 4,
    'critique': 4,
    'high': 3,
    'élevé': 3,
    'important': 3,
    'medium': 2,
    'moyen': 2,
    'low': 1,
    'faible': 1
  };
  return priorities[levelLower] || 0;
}

// Function to get Priority color based on score
function getPriorityColor(score) {
  if (score >= 90) return '#dc3545'; // Critical - Red
  if (score >= 70) return '#fd7e14'; // High - Orange
  if (score >= 40) return '#ffc107'; // Medium - Yellow
  if (score >= 10) return '#28a745'; // Low - Green
  return '#6c757d'; // None/Unknown - Gray
}

// Function to format date
function formatDate(dateString) {
  try {
    const date = new Date(dateString);
    return date.toLocaleDateString('en-US', {
      year: 'numeric',
      month: 'short',
      day: 'numeric'
    });
  } catch (e) {
    return dateString || 'N/A';
  }
}

// Function to filter blogs/bulletins from today and yesterday
function getBlogsFromTodayAndYesterday(bulletins) {
  const now = new Date();
  const today = new Date(now.getFullYear(), now.getMonth(), now.getDate());
  const yesterday = new Date(today.getTime() - 24 * 60 * 60 * 1000);

  console.log('Debug: Filtering bulletins for dates:', yesterday.toDateString(), 'and', today.toDateString());
  console.log('Debug: Total bulletins to filter:', bulletins.length);

  return bulletins.filter(bulletin => {
    // Handle both 'date' and 'Date' field names
    const dateField = bulletin.date || bulletin.Date;
    if (!dateField) {
      console.log('Debug: Bulletin has no date field:', bulletin.Titre || bulletin.title || 'Unknown');
      return false;
    }

    const bulletinDate = new Date(dateField);
    if (isNaN(bulletinDate.getTime())) {
      console.log('Debug: Invalid date format:', dateField);
      return false;
    }

    const bulletinDateOnly = new Date(bulletinDate.getFullYear(), bulletinDate.getMonth(), bulletinDate.getDate());
    const isMatch = bulletinDateOnly.getTime() === yesterday.getTime() || bulletinDateOnly.getTime() === today.getTime();

    const bulletinTitle = bulletin.title || bulletin.Titre || 'Unknown';
    if (isMatch) {
      console.log('Debug: ✅ Including bulletin:', bulletinTitle, bulletinDate.toDateString());
    } else {
      console.log('Debug: ❌ Excluding bulletin:', bulletinTitle, bulletinDate.toDateString());
    }

    return isMatch;
  });
}

