// n8n Code Node - Transform analyzed_bulletins into Elasticsearch bulk NDJSON

// Get all inputs (CVE + Bulletins usually come as array in n8n)
const inputData = $input.all();

let bulletinData = null;

// Find bulletin data inside inputData (usually at index 1)
if (Array.isArray(inputData) && inputData.length >= 2) {
  if (inputData[1] && inputData[1].json && inputData[1].json.analyzed_bulletins) {
    bulletinData = inputData[1].json;
  }
}

// Prepare bulk payload
const bulkData = [];

if (bulletinData && Array.isArray(bulletinData.analyzed_bulletins)) {
  for (const bulletin of bulletinData.analyzed_bulletins) {
    // Build unique doc ID from Source + Date + Titre
    const docId = `${bulletin.Source}_${bulletin.Date}_${bulletin.Titre}`.replace(/\s+/g, "_");

    // Action line
    bulkData.push({
      index: {
        _index: "blogs",
        _id: docId
      }
    });

    // Document body
    bulkData.push({
      source: bulletin.Source,
      titre: bulletin.Titre,
      date: bulletin.Date,
      contenu: bulletin.Contenu,
      link: bulletin.Link,
      criticite: bulletin.criticite,
      type_menace: bulletin.type_menace,
      resume: bulletin.resume,
      secteurs_concernes: bulletin.secteurs_concernes || bulletin.secteurs_concerns || [],
      actions_recommandees: bulletin.actions_recommandees || [],
      urgence: bulletin.urgence,
      score_risque: bulletin.score_risque,
      systemes_affectes: bulletin["systemes affectes"] || bulletin["systemes affectés"] || bulletin["systemes affecte"] || [],
      identificateur_externes: bulletin["identificateur externes"] || bulletin["identificateur_externes"] || [],
      risques: bulletin.risques,
      ingestion_timestamp: new Date().toISOString(),
    });
  }
}

// Convert to NDJSON
const ndjson = bulkData.length > 0 
  ? bulkData.map(item => JSON.stringify(item)).join('\n') + '\n'
  : '';

return [{ json: { bulkData: ndjson } }];
